import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(3.2, 1, 0.06);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Load image texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  // Create text
  const textObj = ctx.fontAtlas.createText('Journal 3', {
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center'
  });
  textObj.position.z = 0.1;
  mesh.add(textObj);

  // Store timelines for cleanup
  const timelines = [];

  // Hover effect: rise-in (subtle, 0.15 scene units)
  const onHoverEnter = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
    timelines.push(tl);
  };

  const onHoverExit = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: 1,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto'
    }, 0);
    timelines.push(tl);
  };

  // Press effect: scale down
  const onPointerDown = () => {
    const tl = gsap.timeline();
    tl.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);
    timelines.push(tl);
  };

  const onPointerUp = () => {
    const tl = gsap.timeline();
    tl.to(mesh.scale, {
      x: 1,
      y: 1,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
    timelines.push(tl);
  };

  // Click effect: emit navigation event
  const onClick = () => {
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // Attach handlers to userData
  mesh.userData.handlers = {
    onHoverEnter,
    onHoverExit,
    onPointerDown,
    onPointerUp,
    onClick
  };

  // Cleanup function
  mesh.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
